/// The name a hash stands for, when the scripts' source names it.
pub fn name_of(hash: u32) -> Option<&'static str> {
    NAMES
        .binary_search_by_key(&hash, |&(known, _)| known)
        .ok()
        .map(|index| NAMES[index].1)
}
